css:
/* ===========================================================================
   2039 Que Se Entienda — Brújula §A
   Identidad propia: sala de subtitulado. Papel blanco puro, tinta casi negra y
   barras de subtítulo quemadas (fondo oscuro, texto blanco, tipografía grande)
   como motivo estructural. Un solo acento violeta eléctrico y un anillo de foco
   amarillo señal que no se puede pasar por alto: la cata que habla de
   accesibilidad se publica accesible o no se publica (§9 del concepto).
   Deliberadamente distinta del 2028 (índigo/ámbar), del 2031 (azul noche/cian),
   del 2035 (ciruela/terracota), del 2030 (hueso/verde pino/ocre) y del 2036
   (papel frío/verde azulado/coral): aquí no hay tarjetas de color, hay contraste.
   =========================================================================== */

.acc2039-container { max-width: 1060px; margin: 0 auto; padding: 22px; background-color: #ffffff; color: #101215; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; font-size: 1rem; line-height: 1.6; border: 3px solid #101215; }

/* --- foco: el detalle que no se negocia --- */
.acc2039-container a:focus,
.acc2039-container button:focus,
.acc2039-container select:focus,
.acc2039-container input:focus,
.acc2039-container textarea:focus { outline: 4px solid #ffd400; outline-offset: 2px; box-shadow: 0 0 0 7px rgba(16, 18, 21, 0.9); }
.acc2039-container a:focus-visible,
.acc2039-container button:focus-visible,
.acc2039-container select:focus-visible,
.acc2039-container input:focus-visible,
.acc2039-container textarea:focus-visible { outline: 4px solid #ffd400; outline-offset: 2px; }

/* --- texto solo para lectores de pantalla --- */
.acc2039-container .acc2039-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

/* --- cabecera: barra de subtítulo quemada --- */
.acc2039-container .acc2039-header { background-color: #101215; color: #ffffff; padding: 24px 26px; margin-bottom: 20px; border-bottom: 6px solid #ffd400; }
.acc2039-container .acc2039-header h1 { margin: 0 0 6px 0; font-size: 2.25rem; line-height: 1.2; font-weight: 800; letter-spacing: -0.01em; color: #ffffff; background-color: #101215; }
.acc2039-container .acc2039-subtitle { margin: 0 0 12px 0; font-size: 1.05rem; color: #f2f3f5; background-color: #101215; }
.acc2039-container .acc2039-claim { margin: 0; font-size: 0.97rem; color: #ffffff; background-color: #101215; }
.acc2039-container .acc2039-badge { display: inline-block; background-color: #ffd400; color: #101215; font-weight: 800; text-transform: uppercase; letter-spacing: 0.09em; padding: 3px 11px; margin-right: 10px; font-size: 0.74rem; }

/* --- tarjetas de estado --- */
.acc2039-container .acc2039-status { display: flex; gap: 14px; margin-bottom: 18px; flex-wrap: wrap; }
.acc2039-container .acc2039-status-card { flex: 1 1 210px; background-color: #ffffff; border: 3px solid #101215; border-top: 8px solid #4b18d9; padding: 12px 16px; }
.acc2039-container .acc2039-status-label { font-size: 0.74rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.1em; color: #33383f; background-color: #ffffff; }
.acc2039-container .acc2039-status-value { font-size: 2.1rem; font-weight: 800; line-height: 1.15; color: #101215; background-color: #ffffff; font-variant-numeric: tabular-nums; }
.acc2039-container .acc2039-status-sub { font-size: 0.87rem; color: #33383f; background-color: #ffffff; }
.acc2039-container .acc2039-clock { color: #4b18d9; background-color: #ffffff; }
.acc2039-container .acc2039-pend { color: #a4001f; background-color: #ffffff; }
.acc2039-container .acc2039-score { color: #101215; background-color: #ffffff; }

/* --- retorno del beat --- */
.acc2039-container .acc2039-feedback { margin-bottom: 18px; }
.acc2039-container .acc2039-fb-inner { background-color: #f5f2ff; border: 3px solid #4b18d9; border-left-width: 12px; padding: 14px 18px; }
.acc2039-container .acc2039-fb-title { font-weight: 800; font-size: 1.02rem; color: #2c0d84; background-color: #f5f2ff; }
.acc2039-container .acc2039-fb-line { color: #101215; background-color: #f5f2ff; margin-bottom: 6px; }
.acc2039-container .acc2039-fb-event { color: #6b0016; background-color: #f5f2ff; font-size: 0.93rem; padding-left: 16px; position: relative; }
.acc2039-container .acc2039-fb-event::before { content: '!'; position: absolute; left: 0; font-weight: 800; color: #a4001f; }
.acc2039-container .acc2039-fb-score { margin-top: 8px; font-weight: 800; color: #101215; background-color: #f5f2ff; border-top: 2px solid #4b18d9; padding-top: 6px; }

/* --- beat --- */
.acc2039-container .acc2039-beat { display: none; margin-bottom: 20px; }
.acc2039-container .acc2039-beat-title { font-size: 1.4rem; font-weight: 800; margin: 0 0 10px 0; color: #ffffff; background-color: #101215; padding: 8px 14px; }
.acc2039-container .acc2039-brief { font-size: 1rem; color: #101215; margin: 0 0 12px 0; }
.acc2039-container .acc2039-role { font-size: 0.93rem; color: #101215; background-color: #fffbe0; border-left: 8px solid #ffd400; padding: 10px 14px; margin-bottom: 16px; }
.acc2039-container .acc2039-sub { font-size: 1.08rem; font-weight: 800; margin: 20px 0 4px 0; color: #101215; border-bottom: 3px solid #101215; padding-bottom: 4px; }
.acc2039-container .acc2039-subsub { font-size: 0.95rem; font-weight: 700; margin: 12px 0 6px 0; color: #101215; }
.acc2039-container .acc2039-hint-line { font-size: 0.9rem; color: #33383f; margin: 0 0 12px 0; }
.acc2039-container .acc2039-note { font-size: 0.9rem; color: #101215; background-color: #f4f4f6; border-left: 8px solid #4b18d9; padding: 10px 14px; margin: 16px 0 0 0; }
.acc2039-container .acc2039-alt { font-size: 0.85rem; color: #33383f; margin: 8px 0 0 0; }

/* --- los tres niveles --- */
.acc2039-container .acc2039-rules { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.acc2039-container .acc2039-rule { flex: 1 1 260px; padding: 10px 14px; background-color: #ffffff; border: 3px solid #101215; }
.acc2039-container .acc2039-rule-t { display: block; font-weight: 800; font-size: 0.95rem; margin-bottom: 3px; }
.acc2039-container .acc2039-rule-d { display: block; font-size: 0.87rem; color: #33383f; }
.acc2039-container .acc2039-rule-3 { border-left: 12px solid #a4001f; }
.acc2039-container .acc2039-rule-2 { border-left: 12px solid #8a4b00; }
.acc2039-container .acc2039-rule-1 { border-left: 12px solid #33383f; }

/* --- rejillas --- */
.acc2039-container .acc2039-tablewrap { overflow-x: auto; border: 3px solid #101215; margin-bottom: 8px; }
.acc2039-container .acc2039-grid { width: 100%; border-collapse: collapse; font-size: 0.9rem; background-color: #ffffff; }
.acc2039-container .acc2039-grid thead th { background-color: #101215; color: #ffffff; text-align: left; font-weight: 800; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; padding: 9px 10px; }
.acc2039-container .acc2039-grid tbody th,
.acc2039-container .acc2039-grid tbody td { padding: 9px 10px; border-top: 2px solid #101215; vertical-align: middle; color: #101215; }
.acc2039-container .acc2039-grid tbody tr:nth-child(even) { background-color: #f4f4f6; }
.acc2039-container .acc2039-err-id,
.acc2039-container .acc2039-frag-id { width: 34px; font-weight: 800; text-align: center; background-color: #101215; color: #ffffff; }
.acc2039-container .acc2039-err-clip { font-weight: 800; white-space: nowrap; }
.acc2039-container .acc2039-err-tc { font-variant-numeric: tabular-nums; white-space: nowrap; font-size: 0.85rem; color: #33383f; }
.acc2039-container .acc2039-strike { text-decoration: line-through 2px #a4001f; color: #6b0016; }
.acc2039-container .acc2039-good { color: #0b4f1c; font-weight: 700; }
.acc2039-container .acc2039-err-sel { min-width: 190px; }
.acc2039-container .acc2039-frag-txt { min-width: 250px; }
.acc2039-container .acc2039-frag-dur { font-variant-numeric: tabular-nums; font-weight: 800; white-space: nowrap; }
.acc2039-container .acc2039-frag-slot { min-width: 150px; }
.acc2039-container .acc2039-frag-int { min-width: 150px; }

/* --- fichas de clip --- */
.acc2039-container .acc2039-clips { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.acc2039-container .acc2039-clip { border: 3px solid #101215; padding: 0 14px 14px 14px; background-color: #ffffff; }
.acc2039-container .acc2039-clip-head { margin: 0 -14px 8px -14px; padding: 8px 14px; background-color: #101215; }
.acc2039-container .acc2039-clip-tag { display: inline-block; background-color: #ffd400; color: #101215; font-weight: 800; padding: 1px 8px; margin-right: 8px; font-size: 0.8rem; }
.acc2039-container .acc2039-clip-title { color: #ffffff; font-weight: 700; font-size: 0.93rem; }
.acc2039-container .acc2039-clip-meta { font-size: 0.86rem; color: #33383f; margin-bottom: 8px; }
.acc2039-container .acc2039-clip-count { font-size: 0.86rem; color: #101215; margin-bottom: 10px; }
.acc2039-container .acc2039-count-n { font-size: 1.7rem; font-weight: 800; color: #a4001f; vertical-align: middle; margin-right: 5px; font-variant-numeric: tabular-nums; }

/* --- escena y huecos --- */
.acc2039-container .acc2039-scene { border: 3px solid #101215; background-color: #f4f4f6; padding: 0 16px 14px 16px; margin-bottom: 18px; }
.acc2039-container .acc2039-scene-t { margin: 0 -16px 10px -16px; padding: 8px 16px; background-color: #101215; color: #ffffff; font-weight: 800; font-size: 0.95rem; }
.acc2039-container .acc2039-scene-d { font-size: 0.93rem; color: #101215; margin-bottom: 12px; }
.acc2039-container .acc2039-gaps { display: flex; gap: 10px; flex-wrap: wrap; }
.acc2039-container .acc2039-gap { flex: 1 1 120px; border: 3px solid #4b18d9; background-color: #ffffff; padding: 8px 12px; }
.acc2039-container .acc2039-gap-n { display: block; font-size: 0.76rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em; color: #2c0d84; }
.acc2039-container .acc2039-gap-s { display: block; font-size: 1.5rem; font-weight: 800; color: #101215; font-variant-numeric: tabular-nums; }
.acc2039-container .acc2039-gap-total { border-color: #101215; background-color: #fffbe0; }

/* --- reparto de horas --- */
.acc2039-container .acc2039-tasks { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.acc2039-container .acc2039-task { border: 3px solid #101215; border-left: 12px solid #4b18d9; padding: 10px 14px; background-color: #ffffff; }
.acc2039-container .acc2039-task-name { font-weight: 800; font-size: 0.95rem; color: #101215; }
.acc2039-container .acc2039-task-meta { font-size: 0.84rem; color: #33383f; margin-bottom: 6px; }
.acc2039-container .acc2039-task-out { font-size: 0.9rem; color: #101215; font-variant-numeric: tabular-nums; }
.acc2039-container .acc2039-task-out strong { font-size: 1.2rem; color: #2c0d84; }

/* --- etiquetas de pista --- */
.acc2039-container .acc2039-tracks { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.acc2039-container .acc2039-track { border: 3px solid #101215; padding: 8px 10px; background-color: #ffffff; }
.acc2039-container .acc2039-track label { font-size: 0.84rem; font-weight: 800; }

/* --- formularios --- */
.acc2039-container .acc2039-set,
.acc2039-container .acc2039-grid2 { border: 3px solid #101215; padding: 14px 16px; margin: 18px 0 0 0; background-color: #ffffff; }
.acc2039-container .acc2039-grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.acc2039-container .acc2039-set legend,
.acc2039-container .acc2039-grid2 legend { font-weight: 800; font-size: 0.95rem; background-color: #101215; color: #ffffff; padding: 4px 12px; width: auto; margin-bottom: 6px; }
.acc2039-container .acc2039-grid2 legend { grid-column: 1 / -1; }
.acc2039-container .acc2039-field { margin-bottom: 12px; }
.acc2039-container label { display: block; font-size: 0.9rem; font-weight: 700; color: #101215; margin-bottom: 5px; }
.acc2039-container select { background-color: #ffffff; color: #101215; border: 3px solid #101215; padding: 8px 10px; width: 100%; font-size: 0.92rem; font-family: inherit; }
.acc2039-container select:hover { border-color: #4b18d9; }
.acc2039-container select option { background-color: #ffffff; color: #101215; }
.acc2039-container textarea { background-color: #ffffff; color: #101215; border: 3px solid #101215; padding: 9px 11px; width: 100%; font-size: 0.93rem; font-family: inherit; line-height: 1.5; resize: vertical; }
.acc2039-container textarea::placeholder { color: #5a6069; opacity: 1; }
.acc2039-container input[type="range"] { width: 100%; height: 30px; accent-color: #4b18d9; background-color: transparent; }
.acc2039-container .acc2039-checks { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 8px; }
.acc2039-container .acc2039-check { display: flex; align-items: flex-start; gap: 10px; font-weight: 400; font-size: 0.91rem; background-color: #f4f4f6; border: 2px solid #101215; padding: 8px 11px; margin-bottom: 0; }
.acc2039-container .acc2039-check-tight { background-color: transparent; border: 0; padding: 0; font-size: 0.86rem; }
.acc2039-container .acc2039-check input[type="checkbox"] { width: 22px; height: 22px; margin: 0; accent-color: #4b18d9; flex: 0 0 auto; }
.acc2039-container .acc2039-readout { font-size: 0.9rem; font-weight: 700; color: #2c0d84; background-color: #f5f2ff; border: 2px dashed #4b18d9; padding: 8px 12px; margin-top: 8px; }

/* --- panel de empleabilidad, con la letra pequeña en el propio panel --- */
.acc2039-container .acc2039-empcard { border: 3px solid #101215; background-color: #ffffff; padding: 0 16px 14px 16px; margin-bottom: 18px; }
.acc2039-container .acc2039-empcard-t { margin: 0 -16px 10px -16px; padding: 8px 16px; background-color: #4b18d9; color: #ffffff; font-weight: 800; font-size: 0.95rem; }
.acc2039-container .acc2039-empcard-list { margin: 0 0 12px 0; padding-left: 22px; font-size: 0.94rem; }
.acc2039-container .acc2039-empcard-list strong { color: #2c0d84; }
.acc2039-container .acc2039-fine { border: 3px solid #a4001f; background-color: #fff5f6; padding: 0 14px 10px 14px; }
.acc2039-container .acc2039-fine-t { margin: 0 -14px 8px -14px; padding: 7px 14px; background-color: #a4001f; color: #ffffff; font-weight: 800; font-size: 0.9rem; }
.acc2039-container .acc2039-fine-list { margin: 0; padding-left: 22px; font-size: 0.92rem; color: #101215; }
.acc2039-container .acc2039-fine-list li { margin-bottom: 4px; }
.acc2039-container .acc2039-assume { font-size: 0.84rem; color: #33383f; margin-top: 10px; border-top: 2px solid #101215; padding-top: 8px; }

/* --- tarjeta de aptitud --- */
.acc2039-container .acc2039-aptcard { border: 3px solid #101215; border-top: 10px solid #ffd400; background-color: #101215; color: #ffffff; padding: 14px 18px; margin-top: 18px; text-align: center; }
.acc2039-container .acc2039-aptcard-t { font-size: 0.86rem; font-weight: 700; color: #f2f3f5; background-color: #101215; }
.acc2039-container .acc2039-aptcard-v { font-size: 2.6rem; font-weight: 800; color: #ffd400; background-color: #101215; font-variant-numeric: tabular-nums; }
.acc2039-container .acc2039-aptcard-s { font-size: 0.95rem; color: #ffffff; background-color: #101215; }

/* --- acciones --- */
.acc2039-container .acc2039-actions { display: flex; gap: 14px; flex-wrap: wrap; margin: 22px 0; }
.acc2039-container .acc2039-btn-primary { background-color: #4b18d9; color: #ffffff; border: 3px solid #101215; padding: 13px 26px; font-size: 1.02rem; font-weight: 800; cursor: pointer; font-family: inherit; transition: background-color 0.2s ease; }
.acc2039-container .acc2039-btn-primary:hover { background-color: #2c0d84; }
.acc2039-container .acc2039-btn-ghost { background-color: #ffffff; color: #101215; border: 3px solid #101215; padding: 13px 22px; font-size: 0.95rem; font-weight: 700; cursor: pointer; font-family: inherit; transition: background-color 0.2s ease; }
.acc2039-container .acc2039-btn-ghost:hover { background-color: #fffbe0; }

/* --- paneles de gráfico e historial --- */
.acc2039-container .acc2039-panels { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 20px; }
.acc2039-container .acc2039-panel { flex: 1 1 380px; border: 3px solid #101215; padding: 0 16px 16px 16px; background-color: #ffffff; }
.acc2039-container .acc2039-panel h3 { margin: 0 -16px 12px -16px; padding: 8px 16px; font-size: 0.93rem; font-weight: 800; background-color: #101215; color: #ffffff; }
.acc2039-container .acc2039-history h3 { margin: 0 0 10px 0; font-size: 1.02rem; font-weight: 800; border-bottom: 3px solid #101215; padding-bottom: 4px; }
.acc2039-container .acc2039-history table { width: 100%; border-collapse: collapse; font-size: 0.88rem; background-color: #ffffff; }
.acc2039-container .acc2039-history table th { background-color: #101215; color: #ffffff; text-align: left; padding: 8px 10px; font-size: 0.76rem; text-transform: uppercase; letter-spacing: 0.05em; }
.acc2039-container .acc2039-history table td { padding: 8px 10px; border-top: 2px solid #101215; color: #101215; }

/* --- mensaje de cierre --- */
.acc2039-container .acc2039-cm { border: 3px solid #101215; background-color: #ffffff; padding: 0 0 18px 0; }
.acc2039-container .acc2039-cm-score { background-color: #101215; color: #ffd400; font-size: 3.2rem; font-weight: 800; text-align: center; padding: 16px 0 4px 0; font-variant-numeric: tabular-nums; }
.acc2039-container .acc2039-cm-max { font-size: 1.2rem; color: #ffffff; background-color: #101215; }
.acc2039-container .acc2039-cm-verdict { background-color: #101215; color: #ffffff; font-size: 1.2rem; font-weight: 800; text-align: center; padding: 0 0 16px 0; }
.acc2039-container .acc2039-cm-kpis { display: flex; flex-wrap: wrap; gap: 0; border-bottom: 3px solid #101215; }
.acc2039-container .acc2039-cm-kpi { flex: 1 1 160px; padding: 10px 14px; font-size: 0.84rem; color: #33383f; border-right: 2px solid #101215; background-color: #f4f4f6; }
.acc2039-container .acc2039-cm-kpi strong { display: block; font-size: 1.4rem; color: #101215; font-variant-numeric: tabular-nums; }
.acc2039-container .acc2039-cm-cap { background-color: #a4001f; color: #ffffff; font-weight: 800; padding: 12px 18px; font-size: 0.95rem; }
.acc2039-container .acc2039-cm-debrief { font-weight: 800; padding: 14px 18px 4px 18px; color: #101215; }
.acc2039-container .acc2039-cm-insights { margin: 0; padding: 0 18px 0 40px; font-size: 0.93rem; }
.acc2039-container .acc2039-cm-insights li { margin-bottom: 6px; }
.acc2039-container .acc2039-cm-cierre { display: flex; flex-direction: column; gap: 5px; margin: 14px 18px 0 18px; padding: 12px 14px; background-color: #f5f2ff; border: 3px solid #4b18d9; font-size: 0.92rem; }
.acc2039-container .acc2039-cm-cierre strong { color: #2c0d84; }
.acc2039-container .acc2039-cm-orid { margin: 14px 18px 0 18px; padding: 10px 14px; background-color: #fffbe0; border-left: 8px solid #ffd400; font-size: 0.9rem; color: #101215; }

@media (prefers-reduced-motion: reduce) {
  .acc2039-container .acc2039-btn-primary,
  .acc2039-container .acc2039-btn-ghost { transition: none; }
}

@media (max-width: 768px) {
  .acc2039-container { padding: 12px; }
  .acc2039-container .acc2039-header h1 { font-size: 1.65rem; }
  .acc2039-container .acc2039-status { flex-direction: column; }
  .acc2039-container .acc2039-status-value { font-size: 1.7rem; }
  .acc2039-container .acc2039-clips { grid-template-columns: 1fr; }
  .acc2039-container .acc2039-tasks { grid-template-columns: 1fr; }
  .acc2039-container .acc2039-tracks { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .acc2039-container .acc2039-grid2 { grid-template-columns: 1fr; }
  .acc2039-container .acc2039-panels { flex-direction: column; }
  .acc2039-container .acc2039-rules { flex-direction: column; }
  .acc2039-container .acc2039-actions { flex-direction: column; }
  .acc2039-container .acc2039-btn-primary,
  .acc2039-container .acc2039-btn-ghost { width: 100%; }
  .acc2039-container .acc2039-cm-score { font-size: 2.4rem; }
}

