        getChartData(state) {
            var t = this._t();
            var ds = (state && state.domainState) || {};
            var mine = (ds.nivel_alumno || []).map(function(v) { return Number(v) || 0; });
            // El nivel de referencia de cada error es la hoja de respuestas del beat 1:
            // no se dibuja hasta que el alumno ha cerrado su clasificación.
            var committed = !!(state && state.currentPeriod > 1);
            var key = committed ? this.ERRORS.map(function(e) { return e.nivel; }) : [];
            var hist = ds.scoreHistory || [];
            var labels = hist.map(function(x, n) { return t('beat_short') + ' ' + (n + 1); });
            return {
                nivelesChart: { datasets: [{ data: mine }, { data: key }] },
                aptitudChart: { labels: labels, datasets: [{ data: hist.slice() }] }
            };
        }

