            ];
        }

        getHint(state, results) {
            var t = this._t();
            var ds = state.domainState;
            if (results.period === 1) {
                if (ds.precision_niveles3 < 4) { return t('hint_b1_n3'); }
                if (ds.veredictos_correctos < 3) { return t('hint_b1_ver'); }
                return t('hint_b1_ok');
            }
            if (results.period === 2) {
                if (!ds.fragmento4_incluido) { return t('hint_b2_cifra'); }
                if (ds.interpretaciones_colocadas > 0) { return t('hint_b2_interpreta'); }
                if (ds.hueco_desbordado) { return t('hint_b2_hueco'); }
                return t('hint_b2_ok');
            }
            if (results.period === 3) {
                if (ds.nivel3_sin_corregir) { return t('hint_b3_barrido'); }
                if (ds.declaracion !== 'c') { return t('hint_b3_decl'); }
                if (ds.etiqueta_falsa) { return t('hint_b3_etiqueta'); }
                return t('hint_b3_ok');
            }
            if (results.period === 4) {
                if (ds.fallo_grave) { return t('hint_b4_hard'); }
                if (ds.calidad_nota < 8) { return t('hint_b4_nota'); }
                return t('hint_b4_ok');
            }
            return null;
        }

        // ---------------------------------------------------------------- cierre

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var t = this._t();
            var ds = window.mySimulation.state.domainState;
            var composite = this._composite(ds);          // misma fórmula, sin deriva
            var performance = this._verdict(composite, ds.fallo_grave);

            var insights = [];
            insights.push(t((ds.precision_niveles >= 8 && ds.precision_niveles3 === 4)
                ? 'insight_niv_ok' : 'insight_niv_gap'));
            insights.push(t(ds.veredictos_correctos === 3 ? 'insight_ver_ok' : 'insight_ver_gap'));
            insights.push(t((ds.fragmento4_incluido && ds.interpretaciones_colocadas === 0)
                ? 'insight_ad_ok' : 'insight_ad_gap'));
            insights.push(t(ds.horas_en_sentido_pct >= this.SENTIDO_TARGET
                ? 'insight_horas_ok' : 'insight_horas_gap'));
            insights.push(t(ds.declaracion === 'c' ? 'insight_decl_ok' : 'insight_decl_gap'));
            insights.push(t(ds.calidad_nota >= 8 ? 'insight_nota_ok' : 'insight_nota_gap'));
            if (ds.fallo_grave) { insights.push(t('insight_hard_fail')); }
            if (ds.gusto <= 2) { insights.push(t('insight_descarte')); }
            insights.push(t('insight_next'));

            var vias = (ds.via_formativa || []).map(function(v) {
                return t('via_lbl_' + v);
            }).join(' · ');

            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                niveles: ds.precision_niveles,
                niveles3: ds.precision_niveles3,
                veredictos: ds.veredictos_correctos,
                interpretaciones: ds.interpretaciones_colocadas,
                segundosAd: ds.segundos_ad_usados,
                horasPct: ds.horas_en_sentido_pct,
                exactitudDecl: ds.exactitud_declaracion,
                calidadNota: ds.calidad_nota,
                hardFail: !!ds.fallo_grave,
                // Las cuatro salidas de la cata que consume el contenedor 2023.
                gusto: ds.gusto,
                motivoGusto: ds.motivo_gusto ? t('menos_lbl_' + ds.motivo_gusto) : '',
                aptitud: this._aptitud(ds),
                aptitudBanda: this._band(this._aptitud(ds), ds.fallo_grave),
                viaFormativa: vias,
                viaOk: !!ds.via_correcta,
                empleabilidadDemanda: t('b4_emp_dv'),
                empleabilidadBanda: t('b4_emp_sv'),
                empleabilidadLeida: !!ds.empleabilidad_leida,
                performance: performance,
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var cap = s.hardFail
                ? '<div class="acc2039-cm-cap">' + t('cm_cap') + '</div>' : '';
            return '<div class="acc2039-cm">'
                + '<div class="acc2039-cm-score">' + score + '<span class="acc2039-cm-max">/100</span></div>'
                + '<div class="acc2039-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="acc2039-cm-kpis">'
                + '<div class="acc2039-cm-kpi">' + t('cm_kpi_niv') + '<strong>' + (s.niveles || 0) + '/10</strong></div>'
                + '<div class="acc2039-cm-kpi">' + t('cm_kpi_ver') + '<strong>' + (s.veredictos || 0) + '/3</strong></div>'
                + '<div class="acc2039-cm-kpi">' + t('cm_kpi_ad') + '<strong>' + this._dec(s.segundosAd || 0) + ' s</strong></div>'
                + '<div class="acc2039-cm-kpi">' + t('cm_kpi_horas') + '<strong>' + (s.horasPct || 0) + ' %</strong></div>'
                + '<div class="acc2039-cm-kpi">' + t('cm_kpi_nota') + '<strong>' + (s.calidadNota || 0) + '/10</strong></div>'
                + '</div>'
                + cap
                + '<div class="acc2039-cm-debrief">' + t('cm_debrief') + '</div>'
                + '<ul class="acc2039-cm-insights">' + items + '</ul>'
                + '<div class="acc2039-cm-cierre">'
                + '<span>' + t('cm_c_gusto') + ' <strong>' + (s.gusto || 0) + '/5</strong> — ' + t('cm_c_gusto_note') + '</span>'
                + '<span>' + t('cm_c_menos') + ' <strong>' + (s.motivoGusto || '') + '</strong></span>'
                + '<span>' + t('cm_c_apt') + ' <strong>' + (s.aptitud || 0) + '/100</strong> (' + t('band_' + (s.aptitudBanda || 1)) + ')</span>'
                + '<span>' + t('cm_c_via') + ' <strong>' + (s.viaFormativa || '') + '</strong></span>'
                + '<span>' + t('cm_c_emp') + ' <strong>' + (s.empleabilidadDemanda || '') + ' · ' + (s.empleabilidadBanda || '') + '</strong></span>'
                + '<span>' + t('cm_c_letra') + '</span>'
                + '</div>'
                + '<div class="acc2039-cm-orid">' + t('cm_orid') + '</div>'
                + '</div>';
        }
